const fs = require('fs');
const path = require('path');
const nodeZlib = require('zlib');

const ZLIB_LIB_DIR = path.resolve(
  __dirname,
  '../../../../../../../packages/imba/polyfills/zlib/zlib-lib'
);

/**
 * Rewrites the (very small) subset of ES module syntax used by the polyfill
 * into CommonJS so that the sources can be evaluated by Node.
 */
function esmToCjs(source) {
  const namedExports = [];
  let code = source;

  // import {a, b} from './mod';
  code = code.replace(
    /^import\s*\{([^}]*)\}\s*from\s*['"]([^'"]+)['"];?[ \t]*$/gm,
    (match, names, spec) => `const {${names}} = require(${JSON.stringify(spec)});`
  );

  // import defaultExport from './mod';
  code = code.replace(
    /^import\s+([A-Za-z_$][\w$]*)\s+from\s*['"]([^'"]+)['"];?[ \t]*$/gm,
    (match, name, spec) =>
      `const ${name} = require(${JSON.stringify(spec)}).default;`
  );

  // export default function foo(...) {}
  code = code.replace(
    /^export\s+default\s+function\s+([A-Za-z_$][\w$]*)/gm,
    (match, name) => {
      namedExports.push(['default', name]);
      return `function ${name}`;
    }
  );

  // export default foo;
  code = code.replace(
    /^export\s+default\s+([A-Za-z_$][\w$]*)\s*;?[ \t]*$/gm,
    (match, name) => {
      namedExports.push(['default', name]);
      return '';
    }
  );

  // export function foo(...) {}
  code = code.replace(
    /^export\s+function\s+([A-Za-z_$][\w$]*)/gm,
    (match, name) => {
      namedExports.push([name, name]);
      return `function ${name}`;
    }
  );

  // export var foo = ...;
  code = code.replace(/^export\s+var\s+([A-Za-z_$][\w$]*)/gm, (match, name) => {
    namedExports.push([name, name]);
    return `var ${name}`;
  });

  if (/^\s*(import|export)\s/m.test(code)) {
    throw new Error('esmToCjs: unsupported module syntax in source');
  }

  code +=
    '\n' +
    namedExports.map(([exp, local]) => `exports.${exp} = ${local};`).join('\n') +
    '\n';

  return code;
}

function createEsmLoader() {
  const cache = new Map();

  function load(filename) {
    const resolved = path.resolve(filename);
    if (cache.has(resolved)) return cache.get(resolved).exports;

    const mod = { exports: {} };
    cache.set(resolved, mod);

    const source = fs.readFileSync(resolved, 'utf8');
    const code = esmToCjs(source);
    const dir = path.dirname(resolved);

    const localRequire = (spec) => {
      if (!spec.startsWith('.')) return require(spec);
      const base = path.resolve(dir, spec);
      const candidate = [base, `${base}.js`, path.join(base, 'index.js')].find(
        (file) => fs.existsSync(file) && fs.statSync(file).isFile()
      );
      if (!candidate) {
        throw new Error(`Cannot find module '${spec}' from '${resolved}'`);
      }
      return load(candidate);
    };

    const fn = new Function(
      'exports',
      'require',
      'module',
      '__filename',
      '__dirname',
      code
    );
    fn(mod.exports, localRequire, mod, resolved, dir);

    return mod.exports;
  }

  return load;
}

const loadModule = createEsmLoader();

const inflateLib = loadModule(path.join(ZLIB_LIB_DIR, 'inflate.js'));
const ZStream = loadModule(path.join(ZLIB_LIB_DIR, 'zstream.js')).default;

const { inflate, inflateInit2, inflateSetDictionary, inflateGetHeader } =
  inflateLib;

/* Public zlib ABI constants (stable, documented values). */
const Z_OK = 0;
const Z_STREAM_END = 1;
const Z_NEED_DICT = 2;
const Z_STREAM_ERROR = -2;
const Z_DATA_ERROR = -3;
const Z_BUF_ERROR = -5;

const Z_NO_FLUSH = 0;
const Z_FINISH = 4;
const Z_BLOCK = 5;
const Z_TREES = 6;

const ZLIB_WINDOW_BITS = 15; // zlib wrapper
const GZIP_WINDOW_BITS = 15 + 16; // gzip wrapper

/* ------------------------------------------------------------------ helpers */

function createInflate(windowBits = ZLIB_WINDOW_BITS) {
  const strm = new ZStream();
  expect(inflateInit2(strm, windowBits)).toBe(Z_OK);
  return strm;
}

function setInput(strm, bytes) {
  strm.input = Uint8Array.from(bytes);
  strm.avail_in = strm.input.length;
  strm.next_in = 0;
}

function makeOutput(strm, size) {
  const buffer = new Uint8Array(size);
  strm.output = buffer;
  strm.avail_out = size;
  strm.next_out = 0;
  return buffer;
}

/**
 * Repeatedly calls inflate() until the stream ends (or an unrecoverable error
 * occurs) and returns everything that was produced.
 */
function runUntilDone(strm, flush, chunkSize) {
  const chunks = [];
  const returnCodes = [];
  let ret = Z_OK;
  let guard = 0;

  while (guard++ < 10000) {
    const buffer = makeOutput(strm, chunkSize);
    ret = inflate(strm, flush);
    returnCodes.push(ret);
    chunks.push(Buffer.from(buffer.subarray(0, chunkSize - strm.avail_out)));
    if (ret !== Z_OK && ret !== Z_BUF_ERROR) break;
  }

  return { ret, returnCodes, output: Buffer.concat(chunks) };
}

/** Runs a plain, single call over a complete stream with a generous buffer. */
function inflateOnce(compressed, windowBits = ZLIB_WINDOW_BITS, flush = Z_FINISH) {
  const strm = createInflate(windowBits);
  setInput(strm, compressed);
  const buffer = makeOutput(strm, Math.max(compressed.length * 4, 1024));
  const ret = inflate(strm, flush);
  return {
    strm,
    ret,
    output: Buffer.from(buffer.subarray(0, buffer.length - strm.avail_out)),
  };
}

/** Standard table driven crc32 (used only to build gzip fixtures). */
function crc32(buffer) {
  let crc = -1;
  for (let i = 0; i < buffer.length; i += 1) {
    crc ^= buffer[i];
    for (let k = 0; k < 8; k += 1) {
      crc = crc & 1 ? 0xedb88320 ^ (crc >>> 1) : crc >>> 1;
    }
  }
  return (crc ^ -1) >>> 0;
}

function gzipHeader({ flags = 0, mtime = 0, xfl = 0, os = 0 } = {}) {
  const header = Buffer.alloc(10);
  header[0] = 0x1f;
  header[1] = 0x8b;
  header[2] = 0x08; // deflate
  header[3] = flags;
  header.writeUInt32LE(mtime >>> 0, 4);
  header[8] = xfl;
  header[9] = os;
  return header;
}

function gzipTrailer(payload) {
  const trailer = Buffer.alloc(8);
  trailer.writeUInt32LE(crc32(payload), 0);
  trailer.writeUInt32LE(payload.length >>> 0, 4);
  return trailer;
}

/**
 * Minimal LSB-first deflate bit writer; Huffman codes are emitted MSB-first as
 * required by the deflate bit stream format.
 */
function bitWriter() {
  const bits = [];
  return {
    bits(value, length) {
      for (let i = 0; i < length; i += 1) bits.push((value >> i) & 1);
      return this;
    },
    code(value, length) {
      for (let i = length - 1; i >= 0; i -= 1) bits.push((value >> i) & 1);
      return this;
    },
    toBuffer() {
      const bytes = [];
      for (let i = 0; i < bits.length; i += 8) {
        let byte = 0;
        for (let j = 0; j < 8 && i + j < bits.length; j += 1) {
          byte |= bits[i + j] << j;
        }
        bytes.push(byte);
      }
      return Buffer.from(bytes);
    },
  };
}

const ZLIB_HEADER = Buffer.from([0x78, 0x9c]);

/* -------------------------------------------------------------------- tests */

describe('inflate() argument and stream validation', () => {
  it('returns Z_STREAM_ERROR when no stream object is given', () => {
    expect(inflate(null, Z_NO_FLUSH)).toBe(Z_STREAM_ERROR);
    expect(inflate(undefined, Z_FINISH)).toBe(Z_STREAM_ERROR);
  });

  it('returns Z_STREAM_ERROR when the stream is not initialised', () => {
    expect(inflate({}, Z_NO_FLUSH)).toBe(Z_STREAM_ERROR);
    expect(
      inflate({ output: new Uint8Array(8), avail_out: 8 }, Z_NO_FLUSH)
    ).toBe(Z_STREAM_ERROR);
  });

  it('returns Z_STREAM_ERROR when no output buffer is attached', () => {
    const strm = createInflate();
    setInput(strm, ZLIB_HEADER);
    strm.output = null;
    strm.avail_out = 0;

    expect(inflate(strm, Z_NO_FLUSH)).toBe(Z_STREAM_ERROR);
  });

  it('returns Z_STREAM_ERROR when input is null but avail_in is non zero', () => {
    const strm = createInflate();
    makeOutput(strm, 16);
    strm.input = null;
    strm.avail_in = 4;

    expect(inflate(strm, Z_NO_FLUSH)).toBe(Z_STREAM_ERROR);
  });

  it('returns Z_BUF_ERROR when there is neither input nor output space', () => {
    const strm = createInflate();
    strm.input = null;
    strm.avail_in = 0;
    makeOutput(strm, 16);

    expect(inflate(strm, Z_NO_FLUSH)).toBe(Z_BUF_ERROR);
    expect(strm.msg).toBe('');
  });
});

describe('inflate() zlib streams', () => {
  const payload = Buffer.from('hello hello hello world');
  const compressed = nodeZlib.deflateSync(payload);

  it('decodes a complete zlib stream and reports Z_STREAM_END', () => {
    const strm = createInflate();
    setInput(strm, compressed);
    const out = makeOutput(strm, 128);

    const ret = inflate(strm, Z_FINISH);

    expect(ret).toBe(Z_STREAM_END);
    expect(strm.msg).toBe('');
    expect(Buffer.from(out.subarray(0, 128 - strm.avail_out))).toEqual(payload);
    expect(strm.total_in).toBe(compressed.length);
    expect(strm.total_out).toBe(payload.length);
    // 64 is the documented "binary data" flag of strm.data_type.
    expect(strm.data_type & 64).toBe(64);
  });

  it('exposes the adler32 checksum of the inflated data', () => {
    const strm = createInflate();
    setInput(strm, compressed);
    makeOutput(strm, 128);

    expect(inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);
    expect(strm.adler).toBe(compressed.readInt32BE(compressed.length - 4));
  });

  it('keeps returning Z_STREAM_END once the stream is finished', () => {
    const strm = createInflate();
    setInput(strm, compressed);
    makeOutput(strm, 128);
    expect(inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);

    const out = makeOutput(strm, 128);
    expect(inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);
    expect(strm.avail_out).toBe(128);
    expect(out.every((byte) => byte === 0)).toBe(true);
  });

  it('decodes stored (uncompressed) deflate blocks', () => {
    const body = Buffer.from('stored block data '.repeat(40));
    const compressedStored = nodeZlib.deflateSync(body, { level: 0 });

    const { ret, output } = inflateOnce(compressedStored);

    expect(ret).toBe(Z_STREAM_END);
    expect(output).toEqual(body);
  });

  it('decodes fixed Huffman (fixed strategy) deflate blocks', () => {
    const body = Buffer.from('fixed huffman strategy '.repeat(30));
    const compressedFixed = nodeZlib.deflateSync(body, {
      strategy: nodeZlib.constants.Z_FIXED,
    });

    const { ret, output } = inflateOnce(compressedFixed);

    expect(ret).toBe(Z_STREAM_END);
    expect(output).toEqual(body);
  });

  it('drains a stream through a one byte output buffer', () => {
    const body = Buffer.from('abcdefghij'.repeat(40));
    const compressedSmall = nodeZlib.deflateSync(body);
    const strm = createInflate();
    setInput(strm, compressedSmall);

    const { ret, returnCodes, output } = runUntilDone(strm, Z_NO_FLUSH, 1);

    expect(ret).toBe(Z_STREAM_END);
    expect(output).toEqual(body);
    expect(returnCodes.every((code) => code === Z_OK || code === Z_STREAM_END)).toBe(
      true
    );
    expect(returnCodes[returnCodes.length - 1]).toBe(Z_STREAM_END);
    expect(strm.total_out).toBe(body.length);
  });

  it('stops as soon as the output buffer is full', () => {
    const strm = createInflate();
    setInput(strm, compressed);
    const out = makeOutput(strm, 10);

    const ret = inflate(strm, Z_NO_FLUSH);

    expect(ret).toBe(Z_OK);
    expect(strm.avail_out).toBe(0);
    expect(strm.total_out).toBe(10);
    expect(strm.avail_in).toBeGreaterThan(0);
    expect(Buffer.from(out.subarray(0, 10))).toEqual(payload.subarray(0, 10));
  });

  it('inflates payloads that do not fit into the 32K sliding window', () => {
    const parts = [];
    for (let i = 0; i < 2500; i += 1) {
      parts.push(`record ${i} ${'payload '.repeat(i % 20)}\n`);
    }
    const body = Buffer.from(parts.join(''));
    expect(body.length).toBeGreaterThan(70000);

    const compressedLarge = nodeZlib.deflateSync(body, { level: 9 });
    const strm = createInflate();
    setInput(strm, compressedLarge);

    const { ret, output } = runUntilDone(strm, Z_FINISH, 10000);

    expect(ret).toBe(Z_STREAM_END);
    expect(output).toEqual(body);
    expect(strm.state.wsize).toBe(32768);
    expect(strm.state.whave).toBe(32768);
  });
});

describe('inflate() incremental input and flush handling', () => {
  const payload = Buffer.from('incremental input payload '.repeat(20));
  const compressed = nodeZlib.deflateSync(payload);

  it('consumes a partial zlib header and waits for more input', () => {
    const strm = createInflate();
    setInput(strm, compressed.subarray(0, 1));
    const out = makeOutput(strm, 1024);

    const first = inflate(strm, Z_NO_FLUSH);

    expect(first).toBe(Z_OK);
    expect(strm.avail_in).toBe(0);
    expect(strm.total_in).toBe(1);
    expect(out.every((byte) => byte === 0)).toBe(true);

    // The rest of the stream may be supplied by replacing the input buffer.
    setInput(strm, compressed.subarray(1));
    expect(inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);
    expect(Buffer.from(out.subarray(0, 1024 - strm.avail_out))).toEqual(payload);
    expect(strm.total_in).toBe(compressed.length);
  });

  it('returns Z_OK for a truncated stream when not asked to finish', () => {
    const strm = createInflate();
    setInput(strm, compressed.subarray(0, compressed.length - 5));
    makeOutput(strm, 1024);

    expect(inflate(strm, Z_NO_FLUSH)).toBe(Z_OK);
    expect(strm.msg).toBe('');
  });

  it('returns Z_BUF_ERROR for a truncated stream with Z_FINISH', () => {
    const strm = createInflate();
    setInput(strm, compressed.subarray(0, compressed.length - 5));
    makeOutput(strm, 1024);

    expect(inflate(strm, Z_FINISH)).toBe(Z_BUF_ERROR);
    expect(strm.msg).toBe('');
  });

  it('returns Z_BUF_ERROR when Z_FINISH has no output room left', () => {
    const strm = createInflate();
    setInput(strm, compressed);
    const out = makeOutput(strm, 12);

    const ret = inflate(strm, Z_FINISH);

    expect(ret).toBe(Z_BUF_ERROR);
    expect(strm.avail_out).toBe(0);
    expect(Buffer.from(out.subarray(0, 12))).toEqual(payload.subarray(0, 12));
    expect(strm.msg).toBe('');
  });

  it('accumulates totals across successive calls', () => {
    const strm = createInflate();
    setInput(strm, compressed);
    makeOutput(strm, 20);

    expect(inflate(strm, Z_NO_FLUSH)).toBe(Z_OK);
    expect(strm.total_out).toBe(20);
    const firstInputTotal = strm.total_in;
    expect(firstInputTotal).toBeGreaterThan(0);

    makeOutput(strm, 4096);
    expect(inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);
    expect(strm.total_out).toBe(payload.length);
    expect(strm.total_in).toBe(compressed.length);
    expect(strm.adler).toBe(compressed.readInt32BE(compressed.length - 4));
  });
});

describe('inflate() gzip support', () => {
  it('decodes a gzip wrapped stream', () => {
    const payload = Buffer.from('gzip payload abcabcabc');
    const compressed = nodeZlib.gzipSync(payload);

    const strm = createInflate(GZIP_WINDOW_BITS);
    setInput(strm, compressed);
    const out = makeOutput(strm, 128);

    const ret = inflate(strm, Z_FINISH);

    expect(ret).toBe(Z_STREAM_END);
    expect(strm.msg).toBe('');
    expect(Buffer.from(out.subarray(0, 128 - strm.avail_out))).toEqual(payload);
    // gzip stores a crc32 trailer rather than an adler32 value.
    expect(strm.adler).toBe(compressed.readInt32LE(compressed.length - 8));
  });

  it('fills in the gzip header structure supplied to inflateGetHeader', () => {
    const payload = Buffer.from('gzip with everything');
    const raw = nodeZlib.deflateRawSync(payload);
    const compressed = Buffer.concat([
      gzipHeader({
        flags: 0x01 | 0x04 | 0x08 | 0x10, // FTEXT | FEXTRA | FNAME | FCOMMENT
        mtime: 0x11223344,
        xfl: 2,
        os: 3,
      }),
      Buffer.from([0x02, 0x00, 0xde, 0xad]), // extra field (length 2)
      Buffer.from('file.txt\0'),
      Buffer.from('a comment\0'),
      raw,
      gzipTrailer(payload),
    ]);

    const strm = createInflate(GZIP_WINDOW_BITS);
    const head = { name: '', comment: '' };
    expect(inflateGetHeader(strm, head)).toBe(Z_OK);
    expect(head.done).toBe(false);

    setInput(strm, compressed);
    const out = makeOutput(strm, 128);
    expect(inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);

    expect(Buffer.from(out.subarray(0, 128 - strm.avail_out))).toEqual(payload);
    expect(head.done).toBe(true);
    expect(head.text).toBe(1);
    expect(head.time).toBe(0x11223344);
    expect(head.xflags).toBe(2);
    expect(head.os).toBe(3);
    expect(head.extra_len).toBe(2);
    expect(Array.from(head.extra)).toEqual([0xde, 0xad]);
    expect(head.name).toBe('file.txt');
    expect(head.comment).toBe('a comment');
    expect(head.hcrc).toBe(0);
  });

  it('rejects a gzip stream with an unknown compression method', () => {
    const compressed = Buffer.concat([
      Buffer.from([0x1f, 0x8b, 0x07, 0x00]),
      Buffer.alloc(6),
      Buffer.alloc(8),
    ]);

    const { ret, strm } = inflateOnce(compressed, GZIP_WINDOW_BITS);

    expect(ret).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe('unknown compression method');
  });

  it('rejects a gzip stream with reserved header flags', () => {
    const compressed = Buffer.concat([
      gzipHeader({ flags: 0x20 }), // reserved flag bit (0xe0 mask)
      Buffer.alloc(8),
    ]);

    const { ret, strm } = inflateOnce(compressed, GZIP_WINDOW_BITS);

    expect(ret).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe('unknown header flags set');
  });

  it('rejects a gzip stream with a header crc mismatch', () => {
    const payload = Buffer.from('hcrc payload data');
    const compressed = Buffer.concat([
      gzipHeader({ flags: 0x02 }), // FHCRC
      Buffer.from([0x00, 0x00]), // deliberately wrong crc16
      nodeZlib.deflateRawSync(payload),
      gzipTrailer(payload),
    ]);

    const { ret, strm } = inflateOnce(compressed, GZIP_WINDOW_BITS);

    expect(ret).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe('header crc mismatch');
  });

  it('rejects a gzip stream with a mismatching length trailer', () => {
    const payload = Buffer.from('gzip length check payload');
    const compressed = Buffer.from(nodeZlib.gzipSync(payload));
    compressed[compressed.length - 1] ^= 0xff;

    const { ret, strm, output } = inflateOnce(compressed, GZIP_WINDOW_BITS);

    expect(ret).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe('incorrect length check');
    expect(output).toEqual(payload);
  });
});

describe('inflate() data errors', () => {
  it('rejects a zlib header with a bad check value and stays in the error state', () => {
    const payload = Buffer.from('abc');
    const compressed = Buffer.from(nodeZlib.deflateSync(payload));
    compressed[1] = 0x00; // breaks the (CMF << 8 | FLG) % 31 rule

    const strm = createInflate();
    setInput(strm, compressed);
    makeOutput(strm, 64);

    expect(inflate(strm, Z_FINISH)).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe('incorrect header check');

    expect(inflate(strm, Z_FINISH)).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe('incorrect header check');
  });

  it('rejects a zlib header with an unknown compression method', () => {
    // CM = 1, FLG = 0x1a so that the FCHECK rule still holds.
    const compressed = Buffer.from([0x71, 0x1a, 0x00, 0x00, 0x00, 0x00]);

    const { ret, strm } = inflateOnce(compressed);

    expect(ret).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe('unknown compression method');
  });

  it('rejects a window that is bigger than the initialised window size', () => {
    const compressed = nodeZlib.deflateSync(Buffer.from('window size check'));

    const strm = createInflate(9);
    setInput(strm, compressed);
    makeOutput(strm, 64);

    expect(inflate(strm, Z_FINISH)).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe('invalid window size');
  });

  it('rejects an invalid deflate block type', () => {
    const compressed = Buffer.concat([
      ZLIB_HEADER,
      Buffer.from([0x07]), // BFINAL = 1, BTYPE = 3 (invalid)
      Buffer.alloc(4),
    ]);

    const { ret, strm } = inflateOnce(compressed);

    expect(ret).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe('invalid block type');
  });

  it('rejects stored blocks whose length fields do not complement', () => {
    const compressed = Buffer.concat([
      ZLIB_HEADER,
      Buffer.from([0x01, 0x05, 0x00, 0x00, 0x00]), // LEN = 5, NLEN = 0
      Buffer.alloc(4),
    ]);

    const { ret, strm } = inflateOnce(compressed);

    expect(ret).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe('invalid stored block lengths');
  });

  it('rejects a corrupted adler32 trailer', () => {
    const payload = Buffer.from('check my adler trailer');
    const compressed = Buffer.from(nodeZlib.deflateSync(payload));
    compressed[compressed.length - 1] ^= 0xff;

    const { ret, strm, output } = inflateOnce(compressed);

    expect(ret).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe('incorrect data check');
    expect(output).toEqual(payload);
  });

  it('rejects a match distance that reaches before the produced output', () => {
    // Fixed Huffman block: literal 'A', length 3, distance 5, end of block.
    const raw = bitWriter()
      .bits(1, 1) // BFINAL
      .bits(1, 2) // BTYPE = 01 (fixed Huffman)
      .code(0x30 + 0x41, 8) // literal 'A'
      .code(0x01, 7) // length symbol 257 => length 3
      .code(3, 5) // distance symbol 3 => distance 5
      .code(0x00, 7) // end of block symbol 256
      .toBuffer();

    const compressed = Buffer.concat([ZLIB_HEADER, raw, Buffer.alloc(4)]);

    const { ret, strm, output } = inflateOnce(compressed);

    expect(ret).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe('invalid distance too far back');
    expect(output.toString()).toBe('A');
  });
});

describe('inflate() with a preset dictionary', () => {
  it('returns Z_NEED_DICT until the dictionary is supplied, then finishes', () => {
    const dictionary = Buffer.from('common dictionary words here');
    const payload = Buffer.from('common dictionary words here and more data');
    const compressed = nodeZlib.deflateSync(payload, { dictionary });

    const strm = createInflate();
    setInput(strm, compressed);
    const out = makeOutput(strm, 256);

    expect(inflate(strm, Z_FINISH)).toBe(Z_NEED_DICT);
    expect(strm.msg).toBe('');
