    expect(lines[0]).toMatch(/^set x\(val\)\{ this\.ααx\.\$set\(val,this,[^,]+, ?'x'\) \}$/);
    // getter
    expect(lines[1]).toMatch(/^get x\(\)\{ return this\.ααx\.\$get\(this,[^,]+, ?'x'\) \}$/);
