    const out = renderField(field, [result.ast, cls, cls.body()]);
    const lines = out.split('\n');

    expect(lines).toHaveLength(3);
    expect(lines[0]).toMatch(/^static set s\(val\)\{/);
    expect(lines[1]).toMatch(/^static get s\(\)\{/);
    expect(lines[2]).toMatch(/^static get ααs\(\)\{/);
    // static accessors pass the class itself, not the prototype
    expect(lines[2]).toMatch(/,A\) \}$/);
    expect(out).not.toContain('A.prototype');
  });

  test('emits attribute accessors for a ClassAttribute', () => {
    const result = compile('class A\n\tattr x');
    const cls = classOf(result);
    const field = fieldNamed(cls, 'x');

    expect(field).toBeInstanceOf(ast.ClassAttribute);
