      const field = manualField({ restIndex: 0 });

      expect(renderField(field, [result.ast, cls, cls._inits])).toBe(
        'this.p = $$ ? $$.p : undefined;\n',
      );
    });

    test('reads the rest object with a ternary and cached access when a default exists', () => {
      const field = manualField({ restIndex: 0, value: defaultValue });

      expect(renderField(field, [result.ast, cls, cls._inits])).toBe(
        'this.p = ($$ && ($0 = $$.p) !== undefined) ? ($0) : 2;\n',
      );
    });

    test('uses the rest param at the given index', () => {
      const field = manualField({ restIndex: 1 });

      expect(renderField(field, [result.ast, cls, cls._inits])).toBe(
        'this.p = deep ? deep.p : undefined;\n',
      );
    });
  });

  test('returns undefined for a ClassAttribute without a value', () => {
    const result = compile('class A\n\tattr x');
    const cls = classOf(result);
    const field = fieldNamed(cls, 'x');

    expect(field.value()).toBeFalsy();
    expect(renderField(field, [result.ast, cls, cls._inits])).toBe(undefined);
  });

  test('emits an assignment for a ClassAttribute with a value', () => {
