    expect(field).toBeInstanceOf(ast.ClassAttribute);
    expect(field.value()).toBeTruthy();
    expect(renderField(field, [result.ast, cls, cls._inits])).toBe(
      'this.x = ($$ && ($0 = $$.x) !== undefined) ? ($0) : 1;\n',
    );
  });
});

