/**
 * Unit tests for `Access#js` in packages/imba/src/compiler/nodes.mjs.
 *
 * `Access#js` is the code generator for member access expressions
 * (`obj.prop`, `obj[expr]`, `obj?.prop`, ...). It is exercised through the
 * public `Node#c()` entry point, which pushes the access node on the compiler
 * stack and then delegates to `js`. A real (but empty) `Root` is compiled once
 * so the stack has a root scope: helper generation (`negIndex$__`) and symbol
 * identifiers need one.
 *
 * The sibling `package.json` marks this folder as ESM so Jest can load the
 * `.mjs` compiler modules that are imported below.
 */
import {
  Access,
  Assign,
  Block,
  Identifier,
  ImplicitAccess,
  Index,
  InterpolatedIdentifier,
  Num,
  Root,
  Self,
  Str,
  STACK,
  Symbol as SymbolNode,
  SymbolIdentifier,
  VarAccess,
} from '../../../../../../packages/imba/src/compiler/nodes.mjs';
import { Token } from '../../../../../../packages/imba/src/compiler/token.mjs';

let rootScope;

beforeAll(() => {
  const root = new Root([], {});
  root.compile({ sourcePath: 'test/access-js.imba' }, { sourceCode: '' });
  rootScope = STACK.root();
});

beforeEach(() => {
  // The compiler stack is a module level singleton; reset it so every test
  // starts from a clean state without compiler options such as `tsc`.
  STACK.reset();
});

/** Compile `access` while the root scope of a real compilation is active. */
function generate(access) {
  let out;
  STACK.withScope(rootScope, () => {
    out = access.c();
  });
  return out;
}

function dot(left, right, op = '.') {
  return generate(new Access(op, left, right));
}

describe('Access#js - identifier like members', () => {
  test('compiles an identifier member as a dot access', () => {
    expect(dot(new Identifier('user'), new Identifier('name'))).toBe(
      'user.name',
    );
  });

  test('compiles a string member that is a valid identifier as a dot access', () => {
    expect(dot(new Identifier('user'), new Str("'name'"))).toBe('user.name');
  });

  test('compiles reserved words and prefixed string members as a dot access', () => {
    expect(dot(new Identifier('user'), new Str("'class'"))).toBe('user.class');
    expect(dot(new Identifier('user'), new Str("'_private'"))).toBe(
      'user._private',
    );
    expect(dot(new Identifier('user'), new Str("'$el'"))).toBe('user.$el');
  });

  test('compiles a valid identifier symbol member as a dot access', () => {
    expect(dot(new Identifier('user'), new SymbolNode(':name'))).toBe(
      'user.name',
    );
  });

  test('wraps a raw token member into an identifier access', () => {
    expect(dot(new Identifier('user'), new Token(2, 'name', 5))).toBe(
      'user.name',
    );
  });
});

