      "user['first-name']",
    );
    expect(dot(new Identifier('user'), new Str("'first name'"))).toBe(
      "user['first name']",
    );
    expect(dot(new Identifier('user'), new Str("'0abc'"))).toBe("user['0abc']");
    expect(dot(new Identifier('user'), new Str('"he said"'))).toBe(
      'user["he said"]',
    );
  });

  test('brackets symbol members that are not valid identifiers', () => {
    expect(dot(new Identifier('user'), new SymbolNode(':0abc'))).toBe(
