      expect(scope.rule.s2).toBe(0);
    });

    test('uses scoped specificity rules', () => {
      const regular = run('.foo', { type: 'scoped' });
      expect(regular.rule.s1).toBe(1);

      const scope = run('self', { type: 'scoped' });
      expect(scope.rule.s1).toBe(2);
    });

    test('allows specificity to be suppressed explicitly', () => {
      const rule = run('.foo', { respecify: false });

      expect(rule.rule.s1).toBe(0);
      expect(rule.rule.s2).toBe(0);
    });

    test('suppresses even computed off-state specificity when respecify is false', () => {
      const rule = run('div@in@important', { respecify: false });

      expect(rule.rule.s1).toBe(0);
      expect(rule.rule.s2).toBe(0);
      expect(rule.hasTransitionStyles).toBe(true);
    });

    test('accumulates specificity for repeated important modifiers', () => {
      const rule = run('div@important@important');

      expect(rule.rule.s1).toBe(2);
      expect(rule.rule.s2).toBe(1);
    });
  });
});
